from __future__ import annotations

from pathlib import Path


SOURCE = Path("production_context_publication_governed.py")
TEST = Path("tests/test_optional_comprehensive_discovery_isolation.py")
DOC = Path("docs/PRODUCTION_DISCOVERY_FAILURE_ISOLATION.md")


def replace_once(text: str, old: str, new: str, *, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{label}: expected one match, found {count}")
    return text.replace(old, new, 1)


def main() -> None:
    source = SOURCE.read_text(encoding="utf-8")
    source = replace_once(
        source,
        "from __future__ import annotations\n\nfrom dataclasses import replace\n",
        "from __future__ import annotations\n\nimport os\nfrom dataclasses import replace\n",
        label="os import",
    )
    source = replace_once(
        source,
        "from operations.comprehensive_market_discovery import (\n    ComprehensiveMarketDiscoveryResult,\n    discover_comprehensive_markets,\n)\n",
        "from operations.certified_investable_catalog import (\n    configured_path as configured_certified_investable_catalog_path,\n)\nfrom operations.comprehensive_market_discovery import (\n    ComprehensiveMarketDiscoveryError,\n    ComprehensiveMarketDiscoveryResult,\n    discover_comprehensive_markets,\n)\n",
        label="comprehensive imports",
    )
    source = replace_once(
        source,
        "from portfolio.state import SQLiteCanonicalPortfolioStore\n",
        "from portfolio.state import SQLiteCanonicalPortfolioStore\nfrom providers.eodhd import EODHDProviderError\n",
        label="eodhd error import",
    )

    blocked_anchor = '''def _blocked(\n    *,\n    cycle_key: str,\n    scheduled_for: datetime,\n    detail: str,\n    instrument_count: int,\n    decision_as_of: datetime | None = None,\n) -> ProductionContextPublicationResult:\n    return ProductionContextPublicationResult(\n        state="blocked",\n        cycle_key=cycle_key,\n        scheduled_for=scheduled_for,\n        decision_as_of=decision_as_of,\n        detail=detail,\n        instrument_count=instrument_count,\n    )\n\n\n'''
    helpers = '''class _UnavailableComprehensiveDiscovery:\n    """Truthful non-authoritative record for an optional provider scope outage."""\n\n    policy_version = "comprehensive-market-discovery.optional-unavailable.v1"\n    lanes: tuple[()] = ()\n    scope_state = "optional_unavailable"\n\n    def __init__(self, *, as_of: datetime, error: Exception) -> None:\n        status_code = getattr(error, "status_code", None)\n        status = "none" if status_code is None else str(status_code)\n        self.identifier = (\n            "comprehensive-market-discovery:optional-unavailable:"\n            + _stamp(as_of)\n        )\n        self.manifest_fingerprint = (\n            f"optional-unavailable:{type(error).__name__}:{status}"\n        )\n        self.limitations = (\n            "Optional comprehensive global-market discovery was unavailable and did not expand the active certified paper universe.",\n            str(error),\n            "The completed opportunity search is scoped to strategic listed wrappers and broad Alpaca/SEC U.S.-security discovery.",\n            "This degraded scope cannot be represented as complete all-market production coverage.",\n        )\n\n    @staticmethod\n    def instruments_for_holdings(_held_symbols):\n        return ()\n\n\ndef _comprehensive_discovery_required(\n    *,\n    probe: ComprehensiveDiscoveryProbe | None,\n    override: bool | None,\n) -> bool:\n    if override is not None:\n        if not isinstance(override, bool):\n            raise TypeError("comprehensive_discovery_required must be a bool or None")\n        return override\n    if probe is not None:\n        return True\n    if configured_certified_investable_catalog_path() is not None:\n        return True\n    return os.getenv(\n        "CAPITAL_INTELLIGENCE_REQUIRE_COMPREHENSIVE_DISCOVERY",\n        "",\n    ).strip().lower() in {"1", "true", "yes", "on"}\n\n\ndef _discover_comprehensive_scope(\n    *,\n    as_of: datetime,\n    held_symbols: tuple[str, ...],\n    tracked_symbols: tuple[str, ...],\n    excluded_symbols: tuple[str, ...],\n    probe: ComprehensiveDiscoveryProbe | None,\n    required: bool,\n):\n    active_probe = probe or discover_comprehensive_markets\n    try:\n        return active_probe(\n            as_of=as_of,\n            held_symbols=held_symbols,\n            tracked_symbols=tracked_symbols,\n            excluded_symbols=excluded_symbols,\n        )\n    except (ComprehensiveMarketDiscoveryError, EODHDProviderError) as error:\n        if required:\n            raise\n        return _UnavailableComprehensiveDiscovery(as_of=as_of, error=error)\n\n\n'''
    source = replace_once(
        source,
        blocked_anchor,
        blocked_anchor + helpers,
        label="discovery helpers",
    )
    source = replace_once(
        source,
        "    comprehensive_discovery_probe: ComprehensiveDiscoveryProbe | None = None,\n    clock: Clock | None = None,\n",
        "    comprehensive_discovery_probe: ComprehensiveDiscoveryProbe | None = None,\n    comprehensive_discovery_required: bool | None = None,\n    clock: Clock | None = None,\n",
        label="function parameter",
    )

    start = source.index("    discovery: EquityDiscoveryResult | None = None\n")
    end = source.index("\n    cash_expected_return =", start)
    new_block = '''    discovery: EquityDiscoveryResult | None = None\n    base_symbols = set(base_universe.symbol_map)\n    held_symbols = tuple(position.symbol for position in tentative.positions)\n    dynamic_holdings = tuple(symbol for symbol in held_symbols if symbol not in base_symbols)\n    try:\n        discovery = (equity_discovery_probe or discover_us_equities)(\n            as_of=decision_as_of,\n            held_symbols=held_symbols,\n            tracked_symbols=tracked_symbols,\n            excluded_symbols=tuple(base_symbols),\n        )\n        discovered = discovery.instruments_for_holdings(held_symbols)\n    except Exception as error:\n        return _blocked(\n            cycle_key=cycle_key,\n            scheduled_for=scheduled,\n            decision_as_of=decision_as_of,\n            detail=(\n                "Broad U.S.-security opportunity discovery is unavailable; a "\n                "no-superior-opportunity conclusion is prohibited: "\n                f"{type(error).__name__}: {error}"\n            ),\n            instrument_count=len(base_universe.instruments),\n        )\n\n    fully_injected_publication = all(\n        item is not None\n        for item in (\n            readiness_probe,\n            cash_probe,\n            evidence_probe,\n            equity_discovery_probe,\n            clock,\n        )\n    )\n    comprehensive_required = _comprehensive_discovery_required(\n        probe=comprehensive_discovery_probe,\n        override=comprehensive_discovery_required,\n    )\n    try:\n        if comprehensive_discovery_probe is None and fully_injected_publication:\n            direct_universe = load_direct_global_market_universe()\n\n            class _InjectedComprehensiveDiscovery:\n                identifier = f"injected-publication:{direct_universe.identifier}"\n                manifest_fingerprint = direct_universe.identifier\n                policy_version = direct_universe.schema_version\n                lanes = ()\n                limitations = ()\n                scope_state = "complete"\n\n                @staticmethod\n                def instruments_for_holdings(_held_symbols):\n                    return direct_universe.instruments\n\n            comprehensive = _InjectedComprehensiveDiscovery()\n        else:\n            comprehensive = _discover_comprehensive_scope(\n                as_of=decision_as_of,\n                held_symbols=held_symbols,\n                tracked_symbols=tracked_symbols,\n                excluded_symbols=tuple(\n                    (*base_symbols, *(item.symbol for item in discovered))\n                ),\n                probe=comprehensive_discovery_probe,\n                required=comprehensive_required,\n            )\n    except Exception as error:\n        return _blocked(\n            cycle_key=cycle_key,\n            scheduled_for=scheduled,\n            decision_as_of=decision_as_of,\n            detail=(\n                "Required certified comprehensive market discovery is unavailable; "\n                "the cycle remains fail-closed: "\n                f"{type(error).__name__}: {error}"\n            ),\n            instrument_count=len(base_universe.instruments) + len(discovered),\n        )\n\n    comprehensive_instruments = comprehensive.instruments_for_holdings(held_symbols)\n    comprehensive_scope_state = str(\n        getattr(comprehensive, "scope_state", "complete")\n    )\n    comprehensive_limitations = tuple(\n        str(item) for item in getattr(comprehensive, "limitations", ())\n    )\n    comprehensive_complete = comprehensive_scope_state == "complete"\n    universe = replace(\n        base_universe,\n        identifier=(\n            f"{base_universe.identifier}+{discovery.identifier}"\n            f"+{comprehensive.identifier}"\n        ),\n        objective=(\n            base_universe.objective\n            + (\n                " Daily broad U.S.-company and comprehensive global-market discovery compete for capital."\n                if comprehensive_complete\n                else " Daily broad U.S.-company discovery competes for capital; optional comprehensive global discovery did not expand this cycle's active certified scope."\n            )\n        ),\n        instruments=tuple(\n            (*base_universe.instruments, *discovered, *comprehensive_instruments)\n        ),\n        limitations=tuple(\n            dict.fromkeys(\n                (*base_universe.limitations,\n                 "Individual U.S. equities enter through broad SEC/Alpaca discovery and begin with a 1% exploratory cap.",\n                 *(\n                     ("Every classified instrument in the complete certified catalog can enter through comprehensive point-in-time discovery when its provider, evidence, and paper capability stack are complete.",)\n                     if comprehensive_complete\n                     else comprehensive_limitations\n                 ),\n                 "Discovery can nominate instruments but cannot choose an action, size a position, construct a portfolio, authorize execution, or enable real money.")\n            )\n        ),\n    )\n'''
    source = source[:start] + new_block + source[end:]

    source = replace_once(
        source,
        '                ("comprehensive_market_manifest", comprehensive.manifest_fingerprint),\n',
        '                ("comprehensive_market_manifest", comprehensive.manifest_fingerprint),\n                ("comprehensive_market_scope", comprehensive_scope_state),\n',
        label="source scope",
    )
    source = replace_once(
        source,
        '        "comprehensive_discovery_manifest_fingerprint": comprehensive.manifest_fingerprint,\n',
        '        "comprehensive_discovery_manifest_fingerprint": comprehensive.manifest_fingerprint,\n        "comprehensive_discovery_scope_state": comprehensive_scope_state,\n        "comprehensive_discovery_required": comprehensive_required,\n        "comprehensive_discovery_limitations": list(comprehensive_limitations),\n',
        label="state scope",
    )
    old_detail = '''            (\n                "Certified strategic cross-asset wrappers and the daily broad U.S.-company "\n                "discovery lane, published complete candidate and exclusion screening, "\n                "marked the canonical portfolio, and persisted company-specific evidence."\n            )\n            if weekday_market_evaluation_scheduled(decision_as_of)\n'''
    new_detail = '''            (\n                (\n                    "Certified strategic cross-asset wrappers, broad U.S.-company discovery, "\n                    "and comprehensive global-market discovery; published complete candidate "\n                    "and exclusion screening, marked the canonical portfolio, and persisted "\n                    "company-specific evidence."\n                )\n                if comprehensive_complete\n                else (\n                    "Certified strategic cross-asset wrappers and completed broad U.S.-company "\n                    "discovery. Optional comprehensive global discovery was unavailable and "\n                    "did not expand the active certified scope; this cycle does not claim "\n                    "complete all-market coverage."\n                )\n            )\n            if weekday_market_evaluation_scheduled(decision_as_of)\n'''
    source = replace_once(source, old_detail, new_detail, label="ready detail")
    SOURCE.write_text(source, encoding="utf-8")

    TEST.write_text(
        '''from __future__ import annotations\n\nimport json\nfrom datetime import datetime, timezone\nfrom types import SimpleNamespace\n\nfrom production_context_publication_governed import (\n    prepare_governed_production_context_for_cycle,\n)\nfrom providers.eodhd import EODHDRetrievalFailure\nfrom tests.test_production_context_publication_runtime import (\n    _bootstrap_cash_portfolio,\n    _equity_discovery_probe,\n    _evidence,\n    _readiness,\n    _settings,\n)\n\n\ndef _unentitled_lse(**_kwargs):\n    raise EODHDRetrievalFailure(\n        resource="active symbol directory LSE",\n        category="http_client_error",\n        retryable=False,\n        status_code=402,\n    )\n\n\ndef test_optional_unentitled_global_directory_does_not_discard_us_search(tmp_path) -> None:\n    settings = _settings(tmp_path)\n    scheduled_for = datetime(2026, 8, 3, 14, 0, tzinfo=timezone.utc)\n    decision_time = datetime(2026, 8, 3, 14, 5, tzinfo=timezone.utc)\n    _bootstrap_cash_portfolio(\n        settings,\n        as_of=datetime(2026, 8, 3, 13, 30, tzinfo=timezone.utc),\n    )\n\n    result = prepare_governed_production_context_for_cycle(\n        settings=settings,\n        scheduled_for=scheduled_for,\n        readiness_probe=lambda _universe: _readiness(decision_time),\n        cash_probe=lambda: SimpleNamespace(date="2026-07-31", value=4.25),\n        evidence_probe=lambda _universe, _as_of: _evidence(decision_time),\n        equity_discovery_probe=_equity_discovery_probe,\n        comprehensive_discovery_probe=_unentitled_lse,\n        comprehensive_discovery_required=False,\n        clock=lambda: decision_time,\n    )\n\n    assert result.ready is True\n    assert result.candidate_count == 15\n    assert "does not claim complete all-market coverage" in result.detail\n    state = json.loads(\n        (tmp_path / "production-context-publication-state.json").read_text(\n            encoding="utf-8"\n        )\n    )\n    assert state["comprehensive_discovery_scope_state"] == "optional_unavailable"\n    assert state["comprehensive_discovery_required"] is False\n    assert any(\n        "HTTP 402" in item\n        for item in state["comprehensive_discovery_limitations"]\n    )\n\n\ndef test_required_unentitled_global_directory_remains_fail_closed(tmp_path) -> None:\n    settings = _settings(tmp_path)\n    scheduled_for = datetime(2026, 8, 3, 14, 0, tzinfo=timezone.utc)\n    decision_time = datetime(2026, 8, 3, 14, 5, tzinfo=timezone.utc)\n    _bootstrap_cash_portfolio(\n        settings,\n        as_of=datetime(2026, 8, 3, 13, 30, tzinfo=timezone.utc),\n    )\n\n    result = prepare_governed_production_context_for_cycle(\n        settings=settings,\n        scheduled_for=scheduled_for,\n        readiness_probe=lambda _universe: _readiness(decision_time),\n        cash_probe=lambda: SimpleNamespace(date="2026-07-31", value=4.25),\n        evidence_probe=lambda _universe, _as_of: _evidence(decision_time),\n        equity_discovery_probe=_equity_discovery_probe,\n        comprehensive_discovery_probe=_unentitled_lse,\n        comprehensive_discovery_required=True,\n        clock=lambda: decision_time,\n    )\n\n    assert result.state == "blocked"\n    assert "Required certified comprehensive market discovery" in result.detail\n    assert "HTTP 402" in result.detail\n''',
        encoding="utf-8",
    )

    DOC.write_text(
        '''# Production discovery failure isolation\n\n## Incident\n\nThe August 3, 2026 07:00 Pacific CIO cycle completed public-information collection\nbut failed before publishing an opportunity universe. EODHD returned HTTP 402 for\nthe LSE active symbol directory. The production publisher placed broad Alpaca/SEC\nU.S.-security discovery and optional comprehensive global discovery in one exception\nboundary, so the unentitled global provider discarded the otherwise valid U.S. scan.\n\n## Correction\n\nThe production publisher now separates the two scopes:\n\n1. Broad Alpaca/SEC U.S.-security discovery remains mandatory. Failure blocks the\n   cycle and prohibits a no-superior-opportunity conclusion.\n2. Comprehensive global discovery is mandatory only when an explicit probe, a\n   configured complete certified investable catalog, or\n   `CAPITAL_INTELLIGENCE_REQUIRE_COMPREHENSIVE_DISCOVERY=true` makes it authoritative.\n3. A known comprehensive-provider or catalog failure in optional mode produces an\n   immutable degraded-scope record and does not discard the completed U.S. search.\n4. The cycle and state file explicitly state that complete all-market coverage was\n   not achieved. No missing global instrument or evidence is fabricated.\n\n## Governance boundary\n\nThis correction does not treat unentitled EODHD data as available, lower a threshold,\ncreate a candidate, authorize a trade, or certify global coverage. It aligns the\nproduction cycle with the existing capability-based paper scope: strategic listed\nwrappers and broad U.S. company discovery can operate while uncertified global lanes\nremain unavailable. Once comprehensive discovery is explicitly certified or required,\nits failure remains fully fail-closed.\n''',
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
